// The API client: types come from api/openapi.yaml (schema.d.ts, generated by
// openapi-typescript, checked in the CI), calls go through openapi-fetch. Every unsafe request
// carries the CSRF header (Hauptplan E74); the session is the cookie the browser sends on its
// own. Errors arrive as ApiError with the Problem Details of the answer (E71).
import { queryOptions } from "@tanstack/react-query";
import createClient, { type Middleware } from "openapi-fetch";

import type { components, paths } from "./schema";

export type Problem = components["schemas"]["Problem"];
export type ValidationProblem = components["schemas"]["ValidationProblem"];
export type Me = components["schemas"]["Me"];
export type RecordData = components["schemas"]["Record"];
export type Page = components["schemas"]["Page"];
export type AuditEntry = components["schemas"]["AuditEntry"];
export type TimelineItem = components["schemas"]["TimelineItem"];
export type TimelineEntry = components["schemas"]["TimelineEntry"];
export type Clock = components["schemas"]["Clock"];
export type Query = components["schemas"]["Query"];
export type Job = components["schemas"]["Job"];
export type MySettings = components["schemas"]["MySettings"];
export type SettingsChange = NonNullable<
  paths["/api/v1/me/settings"]["patch"]["requestBody"]
>["content"]["application/json"];
export type OrgNode = components["schemas"]["OrgNode"];
export type OrgSetting = components["schemas"]["OrgSetting"];
export type PresenceEntry = components["schemas"]["Presence"]["others"][number];
// A form (UI11): sections with questions, bound to fields of the target type or free.
export type FormOffer = components["schemas"]["FormOffer"];
export type FormDefinition = components["schemas"]["FormDefinition"];
export type FormSection = components["schemas"]["FormSection"];
export type FormQuestion = components["schemas"]["FormQuestion"];
export type ListParams = NonNullable<
  paths["/api/v1/records/{typeName}"]["get"]["parameters"]["query"]
>;

export class ApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly problem?: Problem | ValidationProblem,
  ) {
    super(problem?.title ?? `HTTP ${status}`);
    this.name = "ApiError";
  }

  // fieldErrors maps the validation problems of a 422 to field names.
  get fieldErrors(): { field: string; code: string; message: string }[] {
    const errs = (this.problem as ValidationProblem | undefined)?.errors;
    return errs ?? [];
  }
}

// The entity types come from the meta-model at runtime (api/openapi.yaml describes them as an
// open object), so their shape is spelled out here once.
export type Label = Record<string, string>;
export type FieldType =
  "text" | "number" | "boolean" | "date" | "datetime" | "choice" | "reference";
export type Field = {
  name: string;
  type: FieldType;
  label?: Label;
  description?: Label;
  required?: boolean;
  unique?: boolean;
  searchable?: boolean;
  max_length?: number;
  min?: number;
  max?: number;
  options?: { value: string; label?: Label }[];
  to?: string;
  default?: unknown;
  // trait names the trait the field came from; computed fields (the sums of the trait costs,
  // PL20) are kept by the server and never sent.
  trait?: string;
  computed?: boolean;
  // translatable text fields keep a value per language (PL21); the form edits the German one.
  translatable?: boolean;
  // formula makes the field calculated by the server (PL22): shown, never sent.
  formula?: string;
  // format "rich" makes a text field formatted text (UI7): the editor, HTML the server cleans.
  format?: "rich";
  // hidden is set by the customer layer (PL43): left out of forms and lists, kept by the API.
  hidden?: boolean;
  // rollup sums or counts the records of another type that point here (WF13).
  rollup?: { from: string; via: string; op: "sum" | "count"; field?: string; where?: string };
};
export type State = { name: string; label?: Label; initial?: boolean };
export type Transition = { name: string; label?: Label; from: string[]; to: string; when?: string };
// ActorRole is a role at the record (WF3): who may hold it.
export type ActorRole = { name: string; label?: Label; to: string[]; single?: boolean };
// ActorRef is one holder of a role.
export type ActorRef = { type: string; id: string };
export type TypeDefinition = {
  name: string;
  package?: string;
  label?: Label;
  description?: Label;
  title_field?: string;
  fields: Field[];
  states?: State[];
  transitions?: Transition[];
  // traits name the building blocks the type pulls in (PL17): history, timeline (PL42), …
  traits?: string[];
  actors?: ActorRole[];
  // portal offers the type in the portal for users with the fields to create with (UI10).
  portal?: { fields: string[] };
  // revision is the hash of the effective definition, base and customer layer (PL43).
  revision?: string;
};
export type TransitionInfo = components["schemas"]["TransitionInfo"];
// FieldStates is what the field states of the type (WF2) say for a record or a new one.
export type FieldStates = components["schemas"]["FieldStates"];

const csrf: Middleware = {
  onRequest({ request }) {
    request.headers.set("X-Requested-With", "itsm");
    // The form edits the German value of translatable fields until UI3 brings an editor per
    // language (PL21, E98): reading and writing both in German keeps an English browser from
    // saving an English value into the German column.
    request.headers.set("Accept-Language", "de");
    request.headers.set("Content-Language", "de");
    return request;
  },
};

export const client = createClient<paths>({
  // Relative in the browser; the tests run under Node, whose Request needs an absolute URL.
  baseUrl: typeof window === "undefined" ? "http://localhost" : window.location.origin,
  credentials: "same-origin",
  // Resolve fetch at call time, so that tests can replace it after the module loaded.
  fetch: (request) => globalThis.fetch(request),
});
client.use(csrf);

// unwrap turns the {data, error, response} of openapi-fetch into data or ApiError.
function unwrap<T>(result: { data?: T; error?: unknown; response: Response }): T {
  if (result.response.ok) {
    return result.data as T;
  }
  throw new ApiError(result.response.status, result.error as Problem | undefined);
}

export const api = {
  version: async () => unwrap(await client.GET("/api/v1/version")),
  me: async () => unwrap(await client.GET("/api/v1/auth/me")),
  login: async (body: components["schemas"]["Credentials"]) =>
    unwrap(await client.POST("/api/v1/auth/login", { body })),
  providers: async () => unwrap(await client.GET("/api/v1/auth/providers")),
  logout: async () => {
    unwrap(await client.POST("/api/v1/auth/logout"));
  },
  // setTenant switches the session to another tenant (PL44); role and node start afresh.
  setTenant: async (tenant: string) =>
    unwrap(await client.POST("/api/v1/auth/context", { body: { tenant } })),
  changePassword: async (body: components["schemas"]["PasswordChange"]) => {
    unwrap(await client.POST("/api/v1/auth/password", { body }));
  },
  types: async () => unwrap(await client.GET("/api/v1/types")) as unknown as TypeDefinition[],
  list: async (typeName: string, query: ListParams) =>
    unwrap(
      await client.GET("/api/v1/records/{typeName}", { params: { path: { typeName }, query } }),
    ),
  get: async (typeName: string, id: string) =>
    unwrap(
      await client.GET("/api/v1/records/{typeName}/{id}", { params: { path: { typeName, id } } }),
    ),
  create: async (typeName: string, body: RecordData) =>
    unwrap(
      await client.POST("/api/v1/records/{typeName}", { params: { path: { typeName } }, body }),
    ),
  fieldStates: async (typeName: string, body: components["schemas"]["FieldStatesRequest"]) =>
    unwrap(
      await client.POST("/api/v1/records/{typeName}:field-states", {
        params: { path: { typeName } },
        body,
      }),
    ),
  transitions: async (typeName: string, id: string) =>
    unwrap(
      await client.GET("/api/v1/records/{typeName}/{id}/transitions", {
        params: { path: { typeName, id } },
      }),
    ),
  // transition moves the record along its state model (WF1); 409 carries the reason.
  transition: async (typeName: string, id: string, transition: string) =>
    unwrap(
      await client.POST("/api/v1/records/{typeName}/{id}:transition", {
        params: { path: { typeName, id } },
        body: { transition },
      }),
    ),
  // timeline lists entries and history, oldest first (PL42); the page turns it round.
  timeline: async (typeName: string, id: string) =>
    unwrap(
      await client.GET("/api/v1/records/{typeName}/{id}/timeline", {
        params: { path: { typeName, id } },
      }),
    ),
  // query runs a JSON query (E40) for records; the filters of the list use it (UI4).
  query: async (typeName: string, body: Query) =>
    unwrap(
      await client.POST("/api/v1/records/{typeName}:query", {
        params: { path: { typeName } },
        body,
      }),
    ) as Page,
  // upload keeps a file as a temporary file of the session (PL18); an image of the editor
  // (UI7) is shown from /api/v1/files/{id} and attached when the text is saved.
  upload: async (file: File) =>
    unwrap(
      await client.POST("/api/v1/files", {
        params: { query: { name: file.name || "bild.png" } },
        body: file as unknown as string,
        bodySerializer: (b: unknown) => b as BodyInit,
        headers: { "Content-Type": "application/octet-stream" },
      }),
    ),
  // mySettings are the settings of the session's person (UI9), each with its source.
  mySettings: async () => unwrap(await client.GET("/api/v1/me/settings")),
  setMySettings: async (body: SettingsChange) =>
    unwrap(await client.PATCH("/api/v1/me/settings", { body })),
  orgNodes: async () => unwrap(await client.GET("/api/v1/org/nodes")),
  orgSettings: async (path: string) =>
    unwrap(await client.GET("/api/v1/org/nodes/{path}/settings", { params: { path: { path } } })),
  setOrgSetting: async (path: string, key: string, value: unknown) => {
    unwrap(
      await client.PUT("/api/v1/org/nodes/{path}/settings/{key}", {
        params: { path: { path, key } },
        body: value as never,
      }),
    );
  },
  unsetOrgSetting: async (path: string, key: string) => {
    unwrap(
      await client.DELETE("/api/v1/org/nodes/{path}/settings/{key}", {
        params: { path: { path, key } },
      }),
    );
  },
  // beat says the session has the record open (UI8), editing with unsaved changes; the answer
  // is who else has it open.
  beat: async (typeName: string, id: string, editing: boolean) =>
    unwrap(
      await client.PUT("/api/v1/records/{typeName}/{id}/presence", {
        params: { path: { typeName, id } },
        body: { editing },
      }),
    ),
  leave: async (typeName: string, id: string) => {
    unwrap(
      await client.DELETE("/api/v1/records/{typeName}/{id}/presence", {
        params: { path: { typeName, id } },
      }),
    );
  },
  // batch changes chosen records by id and version (UI6); a result per row.
  batch: async (typeName: string, body: components["schemas"]["BatchRequest"]) =>
    unwrap(
      await client.POST("/api/v1/records/{typeName}:batch", {
        params: { path: { typeName } },
        body,
      }),
    ),
  // export asks for the file of a list (UI5): a Blob with its name, or the job of a large one.
  export: async (
    typeName: string,
    body: components["schemas"]["ExportRequest"],
  ): Promise<{ file: Blob; name: string } | { job: Job }> => {
    const result = await client.POST("/api/v1/records/{typeName}:export", {
      params: { path: { typeName } },
      body,
      parseAs: "blob",
    });
    const res = result.response;
    if (res.status === 202) {
      return { job: JSON.parse(await (result.data as Blob).text()) as Job };
    }
    if (!res.ok) {
      const text = await (result.error as Blob | undefined)?.text?.();
      throw new ApiError(res.status, text ? (JSON.parse(text) as Problem) : undefined);
    }
    const disposition = res.headers.get("Content-Disposition") ?? "";
    const name = /filename="?([^";]+)"?/.exec(disposition)?.[1] ?? `export.${body.format}`;
    return { file: result.data as Blob, name };
  },
  job: async (jobId: number) =>
    unwrap(await client.GET("/api/v1/jobs/{jobId}", { params: { path: { jobId } } })),
  // search is the full-text search (PL26) over the types named, best first.
  search: async (q: string, types: string, limit: number) =>
    unwrap(await client.GET("/api/v1/search", { params: { query: { q, types, limit } } })),
  // history is the timeline of a type with history but without the trait timeline.
  history: async (typeName: string, id: string) =>
    unwrap(
      await client.GET("/api/v1/records/{typeName}/{id}/history", {
        params: { path: { typeName, id } },
      }),
    ),
  addEntry: async (typeName: string, id: string, body: string, isPrivate: boolean) =>
    unwrap(
      await client.POST("/api/v1/records/{typeName}/{id}/timeline", {
        params: { path: { typeName, id } },
        // Written with the editor (UI7): HTML, which the server sanitizes.
        body: { body, format: "html", private: isPrivate },
      }),
    ),
  // clocks are the SLA clocks of a record (WF9); 503 where SLAs are not configured.
  clocks: async (typeName: string, id: string) =>
    unwrap(
      await client.GET("/api/v1/records/{typeName}/{id}/clocks", {
        params: { path: { typeName, id } },
      }),
    ),
  // forms are the forms offered to the session (UI11): it may create their target type.
  forms: async () => unwrap(await client.GET("/api/v1/forms")),
  form: async (formId: string) =>
    unwrap(await client.GET("/api/v1/forms/{formId}", { params: { path: { formId } } })),
  // submitForm creates the record of a form; problems name the question ids.
  submitForm: async (formId: string, answers: Record<string, unknown>) =>
    unwrap(
      await client.POST("/api/v1/forms/{formId}:submit", {
        params: { path: { formId } },
        body: { answers },
      }),
    ),
  // update sends If-Match with the version seen; 409 means someone saved in between (E29).
  update: async (typeName: string, id: string, version: number, body: RecordData) =>
    unwrap(
      await client.PATCH("/api/v1/records/{typeName}/{id}", {
        params: { path: { typeName, id }, header: { "If-Match": `"${version}"` } },
        body,
      }),
    ),
};

// meQuery is the session: a 401 means "not signed in" and is not retried.
export const meQuery = queryOptions({
  queryKey: ["me"],
  queryFn: api.me,
  retry: false,
  staleTime: 5 * 60_000,
});

// mySettingsQuery are one's own settings (UI9); the frame applies language, theme and time
// zone from them.
export const mySettingsQuery = queryOptions({
  queryKey: ["me", "settings"],
  queryFn: api.mySettings,
  retry: false,
  staleTime: 5 * 60_000,
});

export const typesQuery = queryOptions({
  queryKey: ["types"],
  queryFn: api.types,
  staleTime: 5 * 60_000,
});

// The ways to sign in besides the local account (PL11); none is the normal case.
export const providersQuery = queryOptions({
  queryKey: ["providers"],
  queryFn: api.providers,
  retry: false,
});

export const versionQuery = queryOptions({
  queryKey: ["version"],
  queryFn: api.version,
  staleTime: Infinity,
});

export const recordQuery = (typeName: string, id: string) =>
  queryOptions({
    queryKey: ["records", typeName, id],
    queryFn: () => api.get(typeName, id),
  });

// fieldStatesQuery asks for a record (id) or a new one; under the record's key, so that a
// transition, which refreshes the record, refreshes them too.
export const fieldStatesQuery = (typeName: string, id?: string) =>
  queryOptions({
    queryKey: id ? ["records", typeName, id, "fieldStates"] : ["fieldStates", typeName, "new"],
    queryFn: () => api.fieldStates(typeName, id ? { id } : {}),
  });

// The parts of a record page live under the record's key: invalidating the key after a save
// or a transition refreshes them all.
// timelineQuery reads the timeline (PL42), or for a type with only the trait history its
// history as a timeline of changes without names.
export const timelineQuery = (typeName: string, id: string, entries = true) =>
  queryOptions({
    queryKey: ["records", typeName, id, "timeline"],
    queryFn: async (): Promise<TimelineItem[]> =>
      entries
        ? api.timeline(typeName, id)
        : (await api.history(typeName, id)).map((change) => ({
            kind: "change" as const,
            at: change.at,
            actor: change.actor,
            change,
          })),
  });

export const clocksQuery = (typeName: string, id: string) =>
  queryOptions({
    queryKey: ["records", typeName, id, "clocks"],
    queryFn: () => api.clocks(typeName, id),
    retry: false,
  });

// childrenQuery lists the records of another type that point at a record (tasks, WF13).
export const childrenQuery = (from: string, via: string, id: string) =>
  queryOptions({
    queryKey: ["records", from, "list", "children", via, id],
    queryFn: () => api.list(from, { limit: 50, filter: { [via]: id } }),
  });

export const transitionsQuery = (typeName: string, id: string) =>
  queryOptions({
    queryKey: ["records", typeName, id, "transitions"],
    queryFn: () => api.transitions(typeName, id),
  });

// qualifiedName is the name the API uses in paths: package.type.
export function qualifiedName(t: TypeDefinition): string {
  return t.package ? `${t.package}.${t.name}` : t.name;
}

// labelOf picks the label in the interface language, then English, then the key itself.
export function labelOf(label: Label | undefined, language: string, fallback: string): string {
  return label?.[language] ?? label?.["en"] ?? fallback;
}
